using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.Tilemaps;using UnityEditor;using UnityEditor.SceneManagement;public static class RemoveMineRails{public static object Main(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.isDirty||EditorApplication.isPlaying)throw new Exception("Clean edit mode required");File.Copy(s.path,"output/scene-review/Main.before-minerails-disk.unity",true);EditorSceneManager.SaveScene(s,"output/scene-review/Main.before-minerails-live.unity",true);var h=GameObject.Find("Hometown");var original=h.transform.Find("The Old Timer").GetComponent<SpriteRenderer>();if(original.sprite.name!="LightGreenCliff_TimberCaveEntrance_WithRails_Assembly")throw new Exception("Unexpected original mine sprite");var extras=h.GetComponentsInChildren<SpriteRenderer>(true).Where(r=>r!=original&&r.sprite!=null&&r.sprite.name=="LightGreenCliff_TimberCaveEntrance_WithRails_Assembly").ToArray();if(extras.Length!=3||extras.Any(r=>r.transform.childCount!=0||r.GetComponents<Component>().Length!=2))throw new Exception("Unexpected extra mine structure");Undo.RecordObject(original,"Remove original mine rails");original.sprite=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/Packs/Cute_Fantasy/Tiles/Cliff/LightGreenCliff_TimberCaveEntrance_WithoutRails_Assembly.png");foreach(var r in extras)Undo.DestroyObjectImmediate(r.gameObject);int cleared=0;foreach(var m in h.GetComponentsInChildren<Tilemap>(true).Where(m=>m.name.Contains("Tracks"))){foreach(var p in m.cellBounds.allPositionsWithin)if(m.HasTile(p))cleared++;Undo.RegisterCompleteObjectUndo(m,"Clear town railway");m.ClearAllTiles();}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s,"output/scene-review/Main.after-minerails-live.unity",true);return new{removedEntrances=extras.Length,clearedTiles=cleared,originalMine=original.name,minerChildren=original.transform.childCount};}}
